CREATE TABLE Satellites (
    satellite_id INT PRIMARY KEY,
    satellite_name VARCHAR(30) NOT NULL UNIQUE,
    orbit_altitude_km INT CHECK (orbit_altitude_km > 0),
    launch_date DATE NOT NULL,
    status VARCHAR(20) DEFAULT 'Active'
);

