select * from usagelogs;

# 1. Work this out in two stages: first tally up each subscription's total number of sessions this month, then use that to shortlist subscriptions with fewer than 5 —
# these may be at risk of cancellation. 
with Monthly_sessions as 
(select subscription_id,
count(*) as Count
from usagelogs 
where month(session_date) = month(curdate()) 
group by subscription_id)
select * from Monthly_sessions 
where count < 5;

# 2. A satellite previously marked as retired has just been reactivated after a successful repair maneuver.
# Update its status to reflect this.
update satellites 
set status ='Retired'
where satellite_id = 35;
select * from satellites;

# 3. For each subscription, looking at its sessions in date order, show what the latency was on the reading immediately before the current one —
# this helps catch any sudden, unexplained connection quality drop. 
select subscription_id,session_date,latency_ms,
lag(latency_ms) over (partition by subscription_id order by session_date) as Previous_latency
from usagelogs;

# 4. Calculate a combined usage score per customer using their total data consumption and session count as an intermediate result,
# then use that to rank countries by overall network engagement. 
With CustomerUsage as 
(select c.customer_id,c.country,
sum(u.data_used_gb) as total_data,
count(u.log_id) as session_count,
(sum(u.data_used_gb) +count(u.log_id)) as Usage_score
from customers c
inner join subscriptions s 
on c.customer_id = s.customer_id
inner join usagelogs u 
on s.subscription_id = u.subscription_id
group by c.customer_id,c.country)
select country,
sum(Usage_score) as Total_engagement,
sum(total_data) as Country_total_data,
sum(session_count) as Country_total_sessions,
rank() over (order by sum(Usage_score) desc) as Engagement_rank
from CustomerUsage
group by country
order by Total_engagement desc;

#5. Identify any subscription that has never logged a single usage session —
# a red flag for the customer success team to investigate.
select s.* 
from subscriptions s 
left join usagelogs u 
on s.subscription_id = u.subscription_id 
where u.log_id is null;

#6. After a recent billing system cleanup, a few usage logs may now point to a subscription ID that no
#longer exists. Track down these orphaned records.
select u.* 
from usagelogs u 
left join subscriptions s 
on u.subscription_id = s.subscription_id
where s.subscription_id is null;

#7. Support agents constantly search usage logs using a specific subscription's ID to pull up its full session
#history instantly, but this lookup has started to feel sluggish now that the log table has grown into the
#tens of thousands. What would you do about it?
create index idx_usage_subscription
on usagelogs(subscription_id);

#8. A billing system recalibration means every monthly fee under one specific plan type needs to be
#adjusted by a fixed percentage. Apply this change to just that plan type's subscriptions.
update subscriptions s 
inner join customers c 
on s.customer_id = c.customer_id
set s.monthly_fee = s.monthly_fee * 1.10
where c.plan_type = 'Premium';

#9. For each plan type, build a running count of new subscriptions signed up over time, ordered by start
#date, to visualize how each plan has grown.
select c.plan_type,s.start_date,
count(*) over (partition by plan_type order by start_date) as Running_total
from subscriptions s 
inner join customers c 
on s.customer_id = c.customer_id;

#10. List all satellites that were launched in the same year as the satellite with the most subscribers.
select * 
from satellites
where year(launch_date) = 
(select year(launch_date) from satellites
where satellite_id =
(select satellite_id 
from subscriptions 
group by satellite_id 
order by count(*) desc 
limit 1));

#11. Within each country, order customers by their total data usage, highest first, to identify the
#network's heaviest users market by market.
select c.country,c.customer_id,
sum(data_used_gb) as Total_data,
rank() over (partition by country order by sum(data_used_gb) desc) as Rnk
from customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id 
inner join usagelogs u 
on s.subscription_id = u.subscription_id
group by c.country,c.customer_id;

#12. Produce a single combined list of every satellite and every subscription together — including
#satellites with zero subscribers and any subscription somehow missing a satellite link — so nothing gets
#left out of the audit.
select sa.satellite_id,sa.satellite_name,s.subscription_id,s.customer_id
from satellites sa 
left join subscriptions s 
on sa.satellite_id = s.satellite_id
group by sa.satellite_id,sa.satellite_name,s.subscription_id,s.customer_id
order by sa.satellite_id;

#13. Prepare a network report listing every subscription along with the customer's name and the satellite
#it's connected to, all on a single line.
select s.subscription_id, c.customer_name, sa.satellite_name
from Subscriptions s
join Customers c
on s.customer_id = c.customer_id
left join Satellites sa
on s.satellite_id = sa.satellite_id
group by s.subscription_id, c.customer_name, sa.satellite_name
order by s.subscription_id;

#14. For each plan type, calculate the total monthly revenue it generates, and highlight any plan type
#contributing less than 10% of total revenue — a pricing strategy question worth raising.
select c.plan_type,
sum(s.monthly_fee) as total_monthly_revenue,
round(sum(s.monthly_fee) * 100.0 /(select sum(s.monthly_fee) from subscriptions),2) as revenue_percentage
from Customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id
group by plan_type
having sum(monthly_fee) * 100.0 /(select sum(monthly_fee) from subscriptions) < 10;

#15. Group all usage logs by subscription, and flag subscriptions with fewer than 3 total sessions recorded
#this month — these customers may be about to churn.
select s.subscription_id,
count(u.log_id) as session_count
from Subscriptions s 
left join UsageLogs u 
on s.subscription_id = u.subscription_id
and year(u.session_date) = year(curdate())
and month(u.session_date) = month(curdate())
group by s.subscription_id, u.session_date
having count(u.log_id) < 3
order by s.subscription_id;

#16. For a satellite currently under review, work out how many days passed between its launch date and
#its very first maintenance record.
select s.satellite_id, s.satellite_name,
datediff(min(m.maintenance_date), s.launch_date) as Days_passed
from Satellites s 
inner join Maintenancerecords m 
on s.satellite_id = m.satellite_id
group by s.satellite_id, s.satellite_name
having s.satellite_id = 30
order by s.satellite_id;

#17. For the customer support dashboard, combine each customer's name and country into a single
#readable label, separated by a comma.
select customer_id,
concat(trim(customer_name), ',', country) as Name_country
from Customers;

#18. The engineering dashboard constantly filters by satellite and maintenance date together, and the
#two filters are almost always used side by side. How would you set the database up so this specific
#combined search runs faster?
create index idx_satellite_maintenancedate 
on maintenancerecords(satellite_id, maintenance_date);
show index from maintenancerecords;

#19. Some satellites may not be serving a single active subscription right now. Identify exactly which
#ones, since this is unused capacity worth flagging.
select sa.satellite_id, sa.satellite_name
from Satellites sa 
left join Subscriptions s 
on sa.satellite_id = s.satellite_id
and s.status = 'Active'
where s.subscription_id is null;

#20. The quarterly network health report needs a single consolidated result: for every satellite, the
#number of subscriptions it serves, their average session latency, the total downtime from maintenance,
#and a clear flag for any satellite whose average latency has crossed an unacceptable threshold.

#21. Group maintenance records by satellite and identify which satellites have had more than 10
#recorded incidents — these may need to be prioritized for early retirement.
select satellite_id, 
count(*) as incident_recorded
from MaintenanceRecords
group by satellite_id
having count(*) > 10;

#22. Flag each satellite as 'Overloaded', 'Balanced', or 'Underutilized' based on how many subscriptions
#are currently linked to it relative to its typical capacity.
with Satellite_usage as
(select sa.satellite_id,sa.satellite_name,
count(s.subscription_id) as Subscription_count
from satellites sa 
left join subscriptions s 
on sa.satellite_id = s.satellite_id
group by sa.satellite_id,sa.satellite_name)
select satellite_id,satellite_name,subscription_count,
case
when subscription_count > (select avg(subscription_count)*1.20
from Satellite_usage) then 'Overloaded'
when subscription_count < (select avg(subscription_count)*0.80
from satellite_usage) then 'Underutilized'
else 'Balanced'
end as Utilization_status
from Satellite_usage;

#23. Count how many active subscriptions currently exist under each plan type.
select c.plan_type,
count(s.subscription_id) as Active_subscriptions
from customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id
where s.status ='Active'
group by c.plan_type
order by Active_subscriptions desc;

#24. Split all customers into three roughly equal usage tiers based on total data consumed, to help design
#three different targeted upsell campaigns.
with CustomerUsage as 
(select c.customer_id,c.customer_name,
sum(u.data_used_gb) as Total_data
from customers c 
left join subscriptions s 
on c.customer_id = s.customer_id
left join usagelogs u 
on s.subscription_id = u.subscription_id
group by c.customer_id,c.customer_name)
select customer_id,customer_name,total_data,
ntile(3) over (order by total_data) as Usage_tier
from CustomerUsage;

#25. Based on session latency, tag each usage log as 'Excellent', 'Acceptable', or 'Poor' connection quality,
#to help support agents quickly diagnose complaints.
select log_id,subscription_id,session_date,latency_ms,
case
when latency_ms <100 then 'Excellent'
when latency_ms <300 then 'Acceptable'
else 'Poor'
end as Connection_quality
from Usagelogs;

#26. First tally each country's total customer count, then bring in revenue details to see which countries
#are generating the most revenue per customer.
with Country_customers as 
(select country,
count(customer_id) as Total_customers
from customers
group by country),
Country_revenue as 
(select c.country,
sum(s.monthly_fee) as Total_revenue
from customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id 
group by c.country)
select cc.country,cc.total_customers,cr.total_revenue,
round(cr.total_revenue / cc.total_customers,2) as Revenue_per_customer
from Country_customers cc 
inner join country_revenue cr 
on cc.country = cr.country
order by Revenue_per_customer desc;

#27. The operations director wants one number for the board meeting: exactly how many customer
#sessions have been logged across the entire network so far.
select count(*) as Total_session 
from UsageLogs;

#28. A data-entry mistake caused an entire batch of customers to be logged under the wrong country.
#Correct this in one sweep rather than customer by customer.
update Customers
set country = 'Egypt'
where country = 'wrongcountry';

#29. After several rounds of database changes, nobody quite remembers what was set up to speed up
#lookups on the usage logs table. Check what's currently in place.
show index from usagelogs;

#30. A usage session arrives logged against a subscription ID that was never created in the system.
#Explain what should happen to this record and why it must not slip through quietly.

#31. The scheduling team wants to know which day of the week sees the highest data usage,
# to plan network maintenance windows around quieter periods.
select session_date, 
sum(data_used_gb) as Highest_data_used,
dayname(session_date) as Day_of_week
from UsageLogs
group by session_date, data_used_gb
order by Highest_data_used desc
limit 1;

#32. A bulk import left several ground station names with accidental leading or trailing spaces.
# Clean these up before they go into the network status report.
set sql_safe_updates = 0;
update groundstations
set station_name = trim(station_name);
set sql_safe_updates = 1;

#33. A batch of very old usage logs from a discontinued legacy billing cycle is cluttering the database and is no longer needed for any analysis.
# Remove exactly those records.
delete from usagelogs 
where session_date < '2025-01-01';

#34. Pull every usage session recorded during the month of March this year, to study seasonal demand
#patterns.
select * 
from usagelogs 
where month(session_date) = 3 
and year(session_date) = year(curdate());

#35. Label each usage session as 'Light' (under 5 GB), 'Moderate' (5-20 GB), or 'Heavy' (above 20 GB), so
#the network team can understand consumption patterns at a glance.
select log_id,subscription_id,data_used_gb,
case
when data_used_gb <5 then 'Light'
when data_used_gb <=20 then 'Moderate'
else 'Heavy'
end as Usage_category
from usagelogs;

#36. Calculate the average downtime per maintenance event, to understand how disruptive a typical
#incident really is.
select avg(downtime_minutes) as Average_downtime_minutes
from maintenancerecords;

#37. A contractor's engagement with the network operations team has just ended, and their access to the
#database needs to be fully withdrawn with immediate effect.
revoke all privileges,
grant option 
from 'contractor_user'@'localhost';
flush privileges;

#38. For the infrastructure report, work out the average orbit altitude across the entire satellite fleet.
select round(avg(orbit_altitude_km), 2) as avg_orbit_alt
from Satellites;

#39. The network engineering team keeps asking for the same list — every satellite with its total
# count and total downtime. Set up something they can pull directly, without you explaining
#the underlying tables every time they ask.
create view SatelliteSummary as
select sa.satellite_id, sa.satellite_name,
count(s.subscription_id) as total_subscriber,
sum(downtime_minutes) as total_downtime
from Satellites sa
inner join Subscriptions s
on sa.satellite_id = s.satellite_id
inner join MaintenanceRecords m
on s.satellite_id = m.satellite_id
group by sa.satellite_id, sa.satellite_name
order by sa.satellite_id ;
select * from SatelliteSummary;

#40. For each subscription, show what the very next session's data usage will be, placed right alongside
#the current one, to help spot a pattern building up across consecutive sessions.
select subscription_id, session_date, data_used_gb,
lead(data_used_gb) over (partition by subscription_id order by session_date, log_id) as Next_session_data_usage
from UsageLogs;

#41. For each satellite, smooth out momentary reporting glitches by calculating an average latency using
#only the current reading and the two immediately before it.
select satellite_id,session_date,latency_ms,
avg(latency_ms) over (
partition by satellite_id order by session_date,log_id
rows between 2 preceding and current row) as Moving_average_latency
from usagelogs u
inner join subscriptions s 
on u.subscription_id = s.subscription_id;

#42. Find the lowest latency ever recorded across the network — this benchmark could be used in the
#next marketing campaign.
select min(latency_ms) as Lowest_Latency
from UsageLogs;

#43. Cross-check satellites against maintenance activity to identify any satellite that has never had a
#single maintenance record — either remarkably reliable or worryingly unmonitored.
select s.satellite_id, s.satellite_name
from  Satellites s
left join MaintenanceRecords m
on s.satellite_id = m.satellite_id
where  m.record_id is null;

#44. Group all customer signups by the exact quarter they joined in, to compare growth across different
#phases of the network's rollout.
select customer_id, customer_name,
year(signup_date) as Year_signedup,
quarter(signup_date) as quarter_signedup
from Customers
group by customer_id, Customer_name
order by customer_id;

#45. An engineer accidentally types a satellite's orbit altitude as a negative number. How do you make
#sure this kind of entry is rejected the moment it's submitted?
alter table satellites
add constraint check_orbit_altitute
check (orbit_altitude_km>=0);

insert into satellites 
(satellite_id, satellite_name, orbit_altitude_km, launch_date)
values
(40, 'OrbitLink-040', -638, '2024-12-14', 'Retired');

#46. Some customer names were typed with inconsistent capitalization during onboarding. Produce a
#clean, uniformly capitalized list for the billing system.
select customer_id,customer_name,
concat(upper(left(customer_name,1)),
lower(substring(customer_name,2))) as Standardized_name
from customers;

#47. For each customer, work out how many days have passed since they signed up — this determines
#who's eligible for the one-year loyalty discount.
select customer_id, customer_name, signup_date,
datediff(curdate(), signup_date) as Days_Passed
from Customers;

#48. List every subscription along with its most recent usage session, making sure subscriptions that
#haven't logged any usage yet still appear on the list rather than disappearing.
select s.subscription_id,s.customer_id,
max(u.session_date) as Most_recent_session
from subscriptions s 
left join usagelogs u 
on s.subscription_id = u.subscription_id
group by s.subscription_id,s.customer_id;

#49. Across the entire network, order every usage session by data consumed to surface the season's
#heaviest sessions, making sure that if two sessions used the exact same amount of data, neither one
#gets unfairly skipped in the ordering.
select log_id,subscription_id,session_date,data_used_gb,
dense_rank() over (order by data_used_gb desc) as Usage_rank
from usagelogs 
order by Usage_rank;

#50. Sort each satellite's launch date into 'Legacy' (before 2021), 'Mid-Generation' (2021-2023), or 'New
#Generation' (after 2023), to help engineers prioritize fleet upgrades.
select satellite_id,satellite_name,launch_date,
case 
when year(launch_date) < 2021 then 'Legacy'
when year(launch_date) between 2021 and 2023 then 'Mid-Generation'
else 'New Generation'
end as Generation_tier
from Satellites;

#51. Find the single highest data usage recorded in one session — this could be a business customer
#running a large upload job worth understanding better.
select log_id,subscription_id,
sum(data_used_gb) as Highest_data_usage
from usagelogs
group by log_id,subscription_id
order by Highest_data_usage desc
limit 1;

#52. The system currently lets someone log a session latency of -40 milliseconds by mistake. What change
#would permanently make this impossible going forward?
alter table usagelogs 
add constraint Check_latency
check (latency_ms >= 0);

#53. Pull every usage log belonging specifically to the one subscription that recorded the highest singlesession data usage in the system.
select * 
from usagelogs
where subscription_id = 
(select subscription_id 
from usagelogs 
order by data_used_gb desc
limit 1);

#54. Find every plan type that has at least one subscriber in a country where the average latency is above
#90 milliseconds.
with CountryLatency as 
(select c.country,
avg(u.latency_ms) as avg_latency
from customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id
inner join usagelogs u 
on s.subscription_id = u.subscription_id
group by c.country)
select distinct 
c.plan_type
from customers c 
inner join CountryLatency cl
on c.country = cl.country
where cl.avg_latency > 90;

#55. Build an intermediate satellite-by-satellite average latency figure, then use it to flag every satellite
#performing worse than the network-wide average.
select s.satellite_id,
avg(u.latency_ms) as Satellite_avg_latency,
(select avg(latency_ms) from usagelogs) as Network_avg_latency,
case
when avg(u.latency_ms) > (select avg(latency_ms) from usagelogs) 
then 'Worse than network average'
else 'Better than network average'
end as Performance_score
from usagelogs u
inner join subscriptions s 
on u.subscription_id = s.subscription_id
group by s.satellite_id;

#56. Track down which satellite is linked to the subscription that recorded the single highest data usage
#anywhere in the entire dataset.
select sa.satellite_id,sa.satellite_name,u.subscription_id,
max(u.data_used_gb) as Highest_Data_used
from Satellites sa
inner join subscriptions s 
on sa.satellite_id = s.satellite_id
inner join Usagelogs u
on s.subscription_id = u.subscription_id
group by sa.satellite_id, sa.satellite_name, u.subscription_id
order by Highest_Data_used desc
limit 1;

#57. The regional expansion team wants to flag any ground station name that's unusually long (more than
#30 characters) so it fits the map interface properly.
select station_id, station_name,
length(station_name) as length_of_station_name
from groundstations
where length(station_name) > 30;

#58. Work out how many distinct countries the customer base currently spans.
select count(distinct country) as Total_countries
from Customers;

#59. Identify every satellite that was launched more than five years ago — these units are approaching
#the end of their expected operational life.
select satellite_id,satellite_name,launch_date
from Satellites
where launch_date < date_sub(curdate(), interval 5 year);

#60. Break this into two steps: first find each subscription's most recent session date, then use that to
#identify which subscriptions have gone quiet in the last 30 days.
With RecentSessions as 
(select subscription_id,
max(session_date) as Latest_session
from usagelogs 
group by subscription_id)
select s.subscription_id,rs.Latest_session
from subscriptions s 
left join RecentSessions rs 
on s.subscription_id = rs.subscription_id 
where rs.latest_session is null
or rs.latest_session < date_sub(curdate(),interval 30 day);

#61. The billing supervisor needs the ability to update subscription fee records directly, unlike the rest of
#the support staff. Set up an access level that reflects this difference.
create role 'billing_supervisor';
grant update on project_3.Subscriptions
to 'billing_supervisor';

grant update (monthly_fee)
on project_3.Subscriptions
to 'billing_supervisor';

#62. The finance team wants to know, in one number, the total monthly revenue currently being
#generated from all active subscriptions.
select sum(monthly_fee) as Total_monthly_Revenue
from Subscriptions
where status = 'Active';

#63. A new customer support agent is joining the team and should only be able to look at customer and
#subscription data, never change any of it. Set up their access accordingly.
create role 'support_agent';

grant select on project_3.Customers
to 'support_agent';

#64. Going forward, the network wants to record which manufacturer built each satellite. Adjust the
#satellite records so this detail can be captured.
alter table Satellites 
add column manufacturer varchar(100);
select Satellite_id, satellite_name, manufacturer
from Satellites;

#65. A support agent tries to save a new subscription without linking it to a customer. What should
#prevent that incomplete record from being saved?
alter table Subscriptions 
modify customer_id int not null;

#66. Count the subscriptions currently linked to each satellite, and shortlist only the satellites carrying
#more than 20 subscribers — these may be nearing capacity.
select sa.satellite_id, sa.satellite_name,
count(s.subscription_id) as total_subscriptions
from Satellites sa 
inner join Subscriptions s 
on sa.satellite_id = s.satellite_id
group by sa.satellite_id, sa.satellite_name
having count(s.subscription_id) > 20
order by sa.satellite_id;

#67. Two onboarding agents in different regions accidentally try to register the same satellite name twice
#during a fleet update. What should stop this from happening?
alter table Satellites
modify satellite_name varchar(30) not null unique;

#68. For every satellite, surface the single highest-usage subscription linked to it without losing any of
#that satellite's other subscription rows in the process — every subscription should still show up in the
#result.
select subscription_id,satellite_id,total_usage
from (select s.subscription_id,s.satellite_id,
sum(u.data_used_gb) as Total_usage,
rank() over (partition by s.satellite_id order by sum(u.data_used_gb) desc) as rnk
from subscriptions s 
left join usagelogs u 
on s.subscription_id = u.subscription_id 
group by s.subscription_id, s.satellite_id) as ranked
where rnk = 1;

#69. Identify which countries have an average session data usage above 20 GB — these markets may
#need additional network capacity.
select c.country,
round(avg(u.data_used_gb),2) as Avg_data_usage
from customers c 
inner join subscriptions s 
on c.customer_id = s.customer_id
inner join usagelogs u 
on s.subscription_id = u.subscription_id 
group by c.country
having avg(u.data_used_gb) >20;

#70. Identify every subscription belonging to whichever single satellite currently has the highest number
#of subscribers.
select s.subscription_id,s.satellite_id,s.customer_id
from subscriptions s 
where s.satellite_id =
(select satellite_id 
from subscriptions 
group by satellite_id
order by count(*) desc
limit 1);

#71. The finance dashboard wants something it can plug straight into its reporting tool that always
#reflects each plan type's current total monthly revenue, without re-deriving it manually every cycle.
create view PlanTypeRevenue as 
select plan_type,
sum(monthly_fee) as Total_monthly_revenue
from subscriptions s 
inner join customers c 
on s.customer_id = c.customer_id
group by plan_type;
select * from PlanTypeRevenue;

#72. For a specific customer flagged for unusual activity, pull all their sessions that occurred between
#midnight and 5 AM.
select u.* 
from usagelogs u 
inner join subscriptions s 
on u.subscription_id = s.subscription_id
where s.customer_id = 101
and time(u.session_date) between '00:00:00' and '05:00:00';

#73. For every ground station, list out all the countries whose customers are being served through that
#station's coverage footprint (matched via country).

#74. For each subscription, flag any of its own sessions where the data usage is noticeably higher than
#that same subscription's own typical usage — a possible sign of a compromised account or a new use
#case.
select subscription_id,session_date,data_used_gb,
avg(data_used_gb) over (partition by subscription_id) as Typical_usage,
case 
when data_used_gb > avg(data_used_gb) over (partition by subscription_id)
then 'Higher than typical'
else 'Normal' 
end as usage_flag
from usagelogs;

#75. The customer support team needs a simplified, always-ready snapshot showing each customer's
#name, plan type, assigned satellite, and most recent session, without agents having to reconstruct the
#full picture from scratch on every call.
create view CustomerSupportSnapshot as
with LatestUsage as 
(select u.subscription_id,u.session_date,
row_number() over (partition by u.subscription_id order by u.session_date desc, u.log_id desc) as rnk
from UsageLogs u)
select c.customer_name,c.plan_type,sa.satellite_name,lu.session_date AS Most_recent_session
from Customers c
inner join Subscriptions s
on c.customer_id = s.customer_id
left join Satellites sa
on s.satellite_id = sa.satellite_id
left join LatestUsage lu
on s.subscription_id = lu.subscription_id
and lu.rnk = 1;
select * from CustomerSupportSnapshot; 




